/* Acervo técnico por obra. Revisões são documentos, compatíveis com a sincronização e backup existentes. */
(function(root){'use strict';
const TYPE='engineering-revision',categories={executivos:'Executivos',telhas:'Telhas',chapas:'Chapas',quantitativos:'Quantitativos',referencias:'Referências e outros'},statuses={draft:'Em elaboração',review:'Em análise',released:'Liberada para execução'},clone=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api,category='executivos',saving=false,editing=false;
const uid=prefix=>prefix+'-'+(root.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),label=n=>'R'+String(n).padStart(2,'0');
const revisionName=r=>String(r.revisionName||'').trim()||label(r.revision);
function validName(value){const name=String(value||'').trim();if(!name||name.length>120)throw Error('Informe um nome para a revisão com até 120 caracteres.');return name}
function revisions(s,p,c){return (s.documents||[]).filter(d=>d.documentType===TYPE&&d.project===p&&d.category===c).sort((a,b)=>b.revision-a.revision)}
function released(s,p,c){return revisions(s,p,c).find(r=>r.status==='released')||null}
function fingerprint(s,p,c){return JSON.stringify(revisions(s,p,c))}
function create(s,p,c,user){if(!s.projects?.some(x=>x.id===p)||!categories[c])throw Error('Selecione uma obra e uma categoria válidas.');const list=revisions(s,p,c),prior=list[0];return {id:uid('PROJ'),documentType:TYPE,project:p,category:c,revision:prior?prior.revision+1:0,revisionName:label(prior?prior.revision+1:0),status:'draft',date:new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),responsible:user?.email||'',summary:'',entries:clone(prior?.entries||[]),attachments:[],sourcePath:'',reading:'Pendente',text:'',textPages:[]}}
function save(s,record,expected,{canEdit=true,isAdmin=false,user=null}={}){
 if(!canEdit)throw Error('Seu acesso é somente de visualização.');
 const r=clone(record),list=revisions(s,r.project,r.category),old=list.find(x=>x.id===r.id);
 if(fingerprint(s,r.project,r.category)!==expected)throw Error('Os projetos foram alterados em outro acesso. Feche e abra novamente antes de salvar.');
 if(!s.projects?.some(p=>p.id===r.project)||!categories[r.category]||!statuses[r.status]||!Number.isInteger(r.revision)||r.revision<0||!r.id)throw Error('Revisão inválida.');
 if(old?.status==='released')throw Error('Revisão liberada não pode ser alterada. Crie uma nova revisão.');
 if(old&&r.revision!==old.revision||!old&&r.revision!==(list.length?list[0].revision+1:0))throw Error('A numeração da revisão mudou. Abra o cadastro novamente.');
 if((s.documents||[]).some(d=>d.id===r.id&&d!==old))throw Error('Identificação de documento já utilizada.');
 if(list.some(d=>d.id!==r.id&&d.revision===r.revision))throw Error('Esta revisão já existe.');
 if(r.status==='released'&&!isAdmin)throw Error('Somente administradores podem liberar uma revisão para execução.');
 if(r.status==='released'&&list.some(d=>d.status==='released'&&d.revision>r.revision))throw Error('Uma revisão mais recente já foi liberada.');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||isNaN(Date.parse(r.date))||new Date(r.date+'T12:00:00Z').toISOString().slice(0,10)!==r.date||!r.responsible?.trim()||!r.summary?.trim())throw Error('Informe data válida, responsável e resumo das alterações.');
 if(!Array.isArray(r.entries)||!r.entries.length)throw Error('Adicione ao menos um projeto.');
 const codes=new Set();for(const e of r.entries){const code=String(e.code||'').trim().toLowerCase();if(!code||!e.title?.trim()||!e.fileRevision?.trim()||codes.has(code))throw Error('Cada projeto precisa de código único, título e revisão própria.');codes.add(code);if(!Array.isArray(e.attachments)||!e.attachments.length||e.attachments.some(f=>!f?.id||!f.name))throw Error('Anexe ao menos um arquivo em cada projeto.');}
 r.revisionName=validName(r.revisionName===undefined?label(r.revision):r.revisionName);
 r.attachments=[...new Map(r.entries.flatMap(e=>e.attachments).map(f=>[f.id,f])).values()];r.name=categories[r.category]+' — '+revisionName(r);r.updatedAt=new Date().toISOString();r.updatedBy=user?.email||'';r.createdAt=old?.createdAt||r.updatedAt;if(r.status==='released'){r.releasedAt=r.updatedAt;r.releasedBy=user?.email||'';}
 const next=clone(s);next.documents=(next.documents||[]).filter(d=>d.id!==r.id).concat(r);next.history=next.history||[];next.history.unshift({id:uid('H'),time:r.updatedAt,kind:'documents',record:r.id,action:r.status==='released'?'Revisão liberada':old?'Revisão atualizada':'Revisão criada',before:old||null,after:clone(r),user:user?.email||''});return next;
}
function rename(s,id,name,expected,{canEdit=false,user=null}={}){
 if(!canEdit)throw Error('Seu acesso é somente de visualização.');
 const old=(s.documents||[]).find(r=>r.id===id&&r.documentType===TYPE);if(!old)throw Error('Revisão não encontrada.');
 if(fingerprint(s,old.project,old.category)!==expected)throw Error('A revisão foi alterada em outro acesso. Abra novamente.');
 const next=clone(s),r=next.documents.find(r=>r.id===id);r.revisionName=validName(name);r.name=categories[r.category]+' — '+r.revisionName;r.updatedAt=new Date().toISOString();r.updatedBy=user?.email||'';
 next.history=next.history||[];next.history.unshift({id:uid('H'),time:r.updatedAt,kind:'documents',record:id,action:'Nome da revisão alterado',before:clone(old),after:clone(r),user:user?.email||''});return next;
}
const btn=(action,text,style='secondary')=>'<button type="button" class="button '+style+'" data-action="ep:'+esc(action)+'">'+esc(text)+'</button>',fmt=d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')?d.slice(8,10)+'/'+d.slice(5,7)+'/'+d.slice(0,4):'—';
function statusText(r,current){return r.status==='released'&&current&&current.id!==r.id?'Substituída':statuses[r.status]||'Em elaboração'}
function filesHTML(e,r){return '<div class="ep-file-list">'+(e.attachments||[]).map((f,i)=>'<article class="ep-file-card"><div class="ep-file-heading"><span class="ep-file-index">'+String(i+1).padStart(2,'0')+'</span><div><strong>'+esc(f.name)+'</strong><small>'+esc((f.name.split('.').pop()||'Arquivo').toUpperCase())+' · Revisão '+esc(e.fileRevision)+'</small></div></div><div class="actions">'+(/\.pdf$/i.test(f.name)?btn('preview:'+r.id+':'+f.id,'Visualizar PDF'):'')+btn('file:'+r.id+':'+f.id,'Baixar arquivo')+'</div></article>').join('')+'</div>'}

function revisionHTML(r,current,details=false){const obsolete=r.status==='released'&&current?.id!==r.id;return '<section class="panel ep-revision"><div class="ep-heading"><div><h2>'+esc(revisionName(r))+' <span class="tag">'+esc(statusText(r,current))+'</span></h2><p>'+fmt(r.date)+' · '+esc(r.responsible)+'</p></div><div class="actions">'+(!details?btn('open:'+r.id,'Abrir'):'')+(api?.canEdit()?btn('rename:'+r.id,'Renomear revisão'):'')+(r.status!=='released'&&api?.canEdit()?btn('edit:'+r.id,'Editar revisão'):'')+'</div></div>'+(obsolete?'<p class="notice">Revisão anterior — substituída. Consulte a revisão liberada atual para execução.</p>':'')+(r.status!=='released'?'<p class="notice neutral">Documento em preparação — ainda não liberado para execução.</p>':'')+'<p>'+esc(r.summary)+'</p>'+(details?'<div class="ep-documents">'+r.entries.map(e=>'<article class="ep-document"><div class="ep-project-heading"><span class="tag">'+esc(e.code)+'</span><h3>'+esc(e.title)+'</h3><p>Revisão do projeto: <strong>'+esc(e.fileRevision)+'</strong></p>'+(e.note?'<p>'+esc(e.note)+'</p>':'')+'</div>'+filesHTML(e,r)+'</article>').join('')+'</div>':'<p>'+r.entries.length+' projeto(s) · '+r.attachments.length+' arquivo(s)</p>')+'</section>'}
function render(s,p,selectedCategory){if(categories[selectedCategory])category=selectedCategory;const selected=s.projects?.find(x=>x.id===p),heading='<div class="page-heading"><div><h1>Projetos — '+esc(categories[category])+'</h1><p>Acervo técnico e revisões por obra.</p></div></div>';if(!selected)return heading+'<section class="panel empty">Selecione uma obra no topo para consultar ou cadastrar seus projetos.</section>';const list=revisions(s,p,category),current=released(s,p,category),latest=list[0];return heading+'<div class="ep-heading"><strong>'+esc(selected.name)+'</strong><div class="actions">'+(api?.canEdit()?btn('new','+ Nova revisão','primary'):'')+(current?btn('zip:'+current.id,'Baixar projetos liberados'):'')+'</div></div>'+(current?'<h2>Liberada para execução</h2>'+revisionHTML(current,current,true):'<p class="notice neutral">Esta categoria ainda não tem uma revisão liberada para execução.</p>')+(latest&&latest.id!==current?.id?'<h2>Revisão mais recente</h2>'+revisionHTML(latest,current):'')+(list.filter(r=>r.id!==current?.id&&r.id!==latest?.id).length?'<details class="panel ep-history"><summary>Revisões anteriores ('+list.filter(r=>r.id!==current?.id&&r.id!==latest?.id).length+')</summary>'+list.filter(r=>r.id!==current?.id&&r.id!==latest?.id).map(r=>revisionHTML(r,current)).join('')+'</details>':'')+(!list.length?'<section class="panel empty">Nenhum projeto cadastrado nesta categoria. Use Nova revisão para enviar o primeiro conjunto.</section>':'')+'<p class="section-note">Cada revisão reúne o conjunto completo desta categoria. Arquivos não alterados mantêm sua revisão própria. A liberação para execução é feita por administrador. Acesso segue a permissão de Documentos.</p>'}
const $=id=>root.document.getElementById(id);
function modal(title,html){$('readerTitle').textContent=title;$('readerContent').innerHTML=html;if(!$('reader').open)$('reader').showModal()}
function editableRow(e,i){return '<article class="ep-document" data-ep-row="'+i+'"><div class="form-grid"><label>Código<input data-ep-field="code" required maxlength="80" value="'+esc(e.code)+'"></label><label>Título<input data-ep-field="title" required maxlength="200" value="'+esc(e.title)+'"></label><label>Revisão do arquivo<input data-ep-field="fileRevision" required maxlength="40" value="'+esc(e.fileRevision)+'"></label><label>Observação<input data-ep-field="note" maxlength="1000" value="'+esc(e.note)+'"></label></div><div class="ep-attachments">'+e.attachments.map(f=>'<span>'+esc(f.name)+' <button type="button" data-ep-remove-file="'+esc(f.id)+'" aria-label="Remover arquivo '+esc(f.name)+'">×</button></span>').join('')+'</div><label>Anexar arquivos (até 20 MB cada)<input type="file" multiple data-ep-files="'+i+'" accept=".pdf,.dwg,.dxf,.xlsx,.xls,.csv,.docx,.doc,.png,.jpg,.jpeg,.zip,.ifc,.rvt"></label><button type="button" class="text-btn red-text" data-ep-remove-row="'+i+'">Remover projeto desta revisão</button></article>'}
function editor(record){if(saving)return;if(!api.canEdit())throw Error('Seu acesso é somente de visualização.');const draft={...clone(record),revisionName:revisionName(record)},expected=fingerprint(api.getState(),draft.project,draft.category),pending=new Map();editing=true;
 function read(){const form=$('epEditor');if(!form)return;for(const k of ['revisionName','date','responsible','summary','status'])draft[k]=form.elements[k].value;for(const row of form.querySelectorAll('[data-ep-row]'))for(const input of row.querySelectorAll('[data-ep-field]'))draft.entries[Number(row.dataset.epRow)][input.dataset.epField]=input.value;}
 function draw(){modal(categories[draft.category]+' — '+revisionName(draft),'<form id="epEditor" class="ep-editor"><p>O conjunto anterior foi aproveitado quando existente. Substitua os arquivos alterados e confira a revisão própria de cada projeto.</p><div class="form-grid"><label>Nome da revisão<input name="revisionName" required maxlength="120" value="'+esc(draft.revisionName)+'" placeholder="Ex.: R04, Revisão A, Projeto aprovado"></label><label>Data<input name="date" type="date" required value="'+esc(draft.date)+'"></label><label>Responsável<input name="responsible" required maxlength="200" value="'+esc(draft.responsible)+'"></label><label>Situação<select name="status">'+Object.entries(statuses).filter(([k])=>k!=='released'||api.isAdmin()).map(([k,t])=>'<option value="'+k+'" '+(draft.status===k?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Resumo das alterações<textarea name="summary" required maxlength="4000">'+esc(draft.summary)+'</textarea></label></div><div>'+draft.entries.map(editableRow).join('')+'</div><div class="actions"><button type="button" id="epAdd" class="button secondary">+ Adicionar projeto</button><button type="submit" class="button primary">Salvar revisão</button><button type="button" id="epCancel" class="button secondary">Cancelar</button></div><p id="epError" class="form-error" role="alert"></p></form>');
 const form=$('epEditor');form.oninput=()=>{editing=true};$('epAdd').onclick=()=>{read();draft.entries.push({code:'',title:'',fileRevision:label(draft.revision),note:'',attachments:[]});draw()};$('epCancel').onclick=()=>{if(saving)return;if(root.confirm('Descartar esta edição ainda não salva?')){editing=false;$('reader').close()}};
 for(const row of form.querySelectorAll('[data-ep-row]')){const i=Number(row.dataset.epRow);row.querySelector('[data-ep-remove-row]').onclick=()=>{read();draft.entries.splice(i,1);draw()};for(const b of row.querySelectorAll('[data-ep-remove-file]'))b.onclick=()=>{read();draft.entries[i].attachments=draft.entries[i].attachments.filter(f=>f.id!==b.dataset.epRemoveFile);draw()};row.querySelector('[data-ep-files]').onchange=async e=>{read();setBusy(true);try{const selected=[...e.target.files],prepared=[];for(const f of selected)prepared.push(await root.LocalFiles.prepare(f));for(const f of prepared){pending.set(f.id,f);const {dataURL,...meta}=f;draft.entries[i].attachments.push(meta)}draw()}catch(error){$('epError').textContent=error.message}finally{setBusy(false)}};}
 form.onsubmit=async event=>{event.preventDefault();if(saving)return;read();try{const options={canEdit:api.canEdit(),isAdmin:api.isAdmin(),user:api.user()},current=api.getState();let next=save(current,draft,expected,options);if(draft.status==='released'&&!root.confirm('Liberar '+revisionName(draft)+' para execução? O conjunto ficará bloqueado para edição.'))return;setBusy(true);const ids=new Set(next.documents.find(d=>d.id===draft.id).attachments.map(f=>f.id));await root.LocalFiles.put([...pending.values()].filter(f=>ids.has(f.id)));if((api.user()?.id||'')!==(options.user?.id||''))throw Error('A sessão mudou. Abra o cadastro novamente.');next=save(api.getState(),draft,expected,{...options,canEdit:api.canEdit(),isAdmin:api.isAdmin()});const ok=await api.save(next);if(ok===false)throw Error('O servidor não confirmou o salvamento. Consulte o aviso de sincronização do sistema antes de tentar novamente.');editing=false;$('reader').close();api.render();api.toast('Revisão salva.')}catch(error){if($('epError'))$('epError').textContent=error.message;else api.toast(error.message)}finally{setBusy(false)}};
 }
 draw();
}
function renameEditor(record){
 if(!api.canEdit())throw Error('Seu acesso é somente de visualização.');
 const expected=fingerprint(api.getState(),record.project,record.category);editing=true;
 modal('Renomear revisão','<form id="epEditor" class="ep-editor"><label>Nome da revisão<input name="revisionName" required maxlength="120" value="'+esc(revisionName(record))+'" placeholder="Ex.: R04, Revisão A, Projeto aprovado"></label><p class="section-note">Escolha livremente o nome exibido para este conjunto.</p><div class="actions"><button type="submit" class="button primary">Salvar nome</button></div><p id="epError" class="form-error" role="alert"></p></form>');
 $('epEditor').onsubmit=async event=>{event.preventDefault();if(saving)return;try{const next=rename(api.getState(),record.id,$('epEditor').elements.revisionName.value,expected,{canEdit:api.canEdit(),user:api.user()});setBusy(true);const ok=await api.save(next);if(ok===false)throw Error('O servidor não confirmou o salvamento. Consulte o aviso de sincronização.');editing=false;$('reader').close();api.render();api.toast('Nome da revisão atualizado.')}catch(error){$('epError').textContent=error.message}finally{setBusy(false)}};
}
function setBusy(value){saving=value;for(const el of root.document.querySelectorAll('#epEditor input,#epEditor textarea,#epEditor select,#epEditor button'))el.disabled=value}
async function openFile(r,id,preview){const meta=r.attachments.find(f=>f.id===id);if(!meta)throw Error('Anexo não encontrado.');if(!preview)return root.LocalFiles.download(id,meta);if(!/\.pdf$/i.test(meta.name))throw Error('Prévia disponível somente para PDF.');const [f]=await root.LocalFiles.load([id]),blob=root.LocalFiles.blob(f),url=URL.createObjectURL(new Blob([blob],{type:'application/pdf'}));modal('PDF — '+meta.name,'<p>'+esc(r.name)+' · '+esc(statusText(r,released(api.getState(),r.project,r.category)))+'</p><iframe class="ep-pdf" title="'+esc(meta.name)+'" src="'+esc(url)+'"></iframe><p>'+btn('file:'+r.id+':'+id,'Baixar PDF')+btn('open:'+r.id,'Voltar à revisão')+'</p>');setTimeout(()=>URL.revokeObjectURL(url),120000)}
function zipPath(r,e,f,index){const safe=v=>String(v).replace(/[\\/\x00-\x1f:*?"<>|]/g,'_').replace(/^\.+/,'_');return safe(revisionName(r))+'/'+safe(e.code)+'/'+(index+1)+'-'+safe(f.name)}
async function downloadZip(r){if(r.status!=='released')throw Error('Selecione uma revisão liberada.');if(!root.JSZip)throw Error('Compactador indisponível. Baixe os arquivos individualmente.');const zip=new root.JSZip();for(const e of r.entries)for(const [i,meta]of e.attachments.entries()){const [file]=await root.LocalFiles.load([meta.id]);zip.file(String(r.entries.indexOf(e)+1)+'-'+zipPath(r,e,meta,i),root.LocalFiles.blob(file))}const result=await zip.generateAsync({type:'blob'}),url=URL.createObjectURL(result),a=root.document.createElement('a');a.href=url;a.download='Projetos-'+categories[r.category]+'-'+revisionName(r).replace(/[\\/\x00-\x1f:*?"<>|]/g,'_')+'.zip';root.document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function handle(action){if(!action?.startsWith('ep:'))return false;const [verb,id,fileId]=action.slice(3).split(':');(async()=>{if(saving)throw Error('Aguarde o salvamento.');const s=api.getState(),p=api.getProject();if(verb==='tab'){if(categories[id]){category=id;api.render()}return}if(verb==='new')return editor(create(s,p,category,api.user()));const r=(s.documents||[]).find(d=>d.id===id&&d.documentType===TYPE&&d.project===p);if(!r)throw Error('Revisão não encontrada para a obra selecionada.');if(verb==='rename')return renameEditor(r);if(verb==='edit')return editor(r);if(verb==='open'){editing=false;return modal(r.name,revisionHTML(r,released(s,r.project,r.category),true))}if(verb==='file'||verb==='preview')return openFile(r,fileId,verb==='preview');if(verb==='zip')return downloadZip(r)})().catch(error=>api.toast(error.message));return true}
root.EngefexEngineeringProjects={TYPE,categories,statuses,revisions,released,fingerprint,create,save,rename,revisionName,render,handle,zipPath,init:value=>api=value,busy:()=>saving,isDirty:()=>editing&&!!root.document?.getElementById('epEditor')&&!!root.document?.getElementById('reader')?.open,closed:()=>{editing=false}};
})(typeof window==='undefined'?globalThis:window);
